package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.math.BigDecimal;
import mockwebserver3.MockResponse;
import mockwebserver3.MockWebServer;
import mockwebserver3.junit5.internal.MockWebServerExtension;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.web.client.RestClient;

/**
 * Verifies the wire contract with the payment provider's REST API: what we send in the
 * authorization request, and how we interpret every answer it can give back, including
 * an outright refusal.
 */
@ExtendWith(MockWebServerExtension.class)
class HttpPaymentGatewayTest {

    private MockWebServer server;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startServer() throws Exception {
        server = new MockWebServer();
        server.start();
        var client = RestClient.builder().baseUrl(server.url("/").toString()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopServer() throws Exception {
        server.shutdown();
    }

    @Test
    void sends_the_reference_amount_and_currency_as_the_provider_expects() throws Exception {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"approved\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        var recorded = server.takeRequest();
        assertThat(recorded.getMethod()).isEqualTo("POST");
        assertThat(recorded.getUrl().encodedPath()).isEqualTo("/v1/authorizations");
        assertThat(recorded.getHeaders().get("Content-Type")).contains("application/json");
        assertThat(recorded.getBody().utf8()).isEqualTo("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}");
    }

    @Test
    void an_approved_answer_is_read_back_as_approved() {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"approved\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_back_as_declined() {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"declined\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_request_outright_is_read_back_as_declined() {
        server.enqueue(new MockResponse.Builder()
                .code(402)
                .build());

        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void any_other_error_from_the_provider_is_not_silently_swallowed() {
        server.enqueue(new MockResponse.Builder()
                .code(500)
                .build());

        assertThatThrownBy(() -> gateway.authorize("ORD-7", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
}

