        var outcome = gateway.authorize("ORD-7", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void any_other_error_from_the_provider_is_not_silently_swallowed() {
        server.enqueue(new MockResponse().setResponseCode(500));

        assertThatThrownBy(() -> gateway.authorize("ORD-7", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }
